function cdqPdfDriveUrlV2275(id){
  id=String(id||'');
  if(!/^[\\w-]+$/.test(id))throw new Error('Identifiant PDF invalide.');
  return 'https://drive.google.com/file/d/'+encodeURIComponent(id)+'/view?usp=drivesdk';
}

function cdqPdfDriveIntentV2275(id){
  const drive=cdqPdfDriveUrlV2275(id);
  if(!/Android/i.test(navigator.userAgent||''))return drive;
  return 'intent://drive.google.com/file/d/'+encodeURIComponent(String(id||''))+
    '/view#Intent;scheme=https;package=com.google.android.apps.docs;'+
    'S.browser_fallback_url='+encodeURIComponent(drive)+';end';
}

function cdqOuvrirPdfCommeSheetV2275(id){
  const pref=cdqPdfReaderPreference();

  // Le lecteur CDQ reste volontairement interne.
  if(pref==='cdq'){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(navigator.onLine===false){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  cdqMarquerPdfOuvertV2275(id);

  // Même principe que Google Sheets : l'intent est lancé DIRECTEMENT
  // pendant le geste utilisateur, sans Apps Script asynchrone, sans
  // window.open tardif et sans page about:blank.
  window.location.href=cdqPdfDriveIntentV2275(id);
  return true;
}

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    return cdqOuvrirPdfCommeSheetV2275(id);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }

  return cdqV19OldModify(id);
};

// Filet de sécurité Android : certains anciens gestionnaires de swipe
// consomment le click synthétique après pointerup. On déclenche donc le PDF
// au pointerup, pendant le vrai geste, puis on supprime seulement le click
// qui suit afin d'éviter une double ouverture.
(function(){
  if(!/Android/i.test(navigator.userAgent||''))return;

  let tap=null;

  document.addEventListener('pointerdown',function(e){
    if(e.target&&e.target.closest&&e.target.closest('button'))return;
    const row=e.target&&e.target.closest?e.target.closest('.file-row'):null;
    if(!row)return;
    const box=row.querySelector('.file-checkbox[data-file-id]');
    if(!box)return;
    const id=String(box.dataset.fileId||'');
    const meta=cdqDocumentMeta(id);
    if(!meta||meta.type!=='PDF')return;
    tap={row:row,id:id,pointerId:e.pointerId,x:e.clientX,y:e.clientY,moved:false};
  },true);

  document.addEventListener('pointermove',function(e){
    if(!tap||tap.pointerId!==e.pointerId)return;
    if(Math.abs(e.clientX-tap.x)>18||Math.abs(e.clientY-tap.y)>18)tap.moved=true;
  },true);

  document.addEventListener('pointercancel',function(e){
    if(tap&&tap.pointerId===e.pointerId)tap=null;
  },true);

  document.addEventListener('pointerup',function(e){
    if(!tap||tap.pointerId!==e.pointerId)return;
    const t=tap;tap=null;

    if(t.moved)return;
    if(typeof modeSelectionFichiers!=='undefined'&&modeSelectionFichiers)return;
    if(e.target&&e.target.closest&&e.target.closest('button'))return;

    t.row.dataset.cdqPdfOpenedV2275='1';
    try{
      cdqOuvrirPdfCommeSheetV2275(t.id);
    }catch(err){
      try{afficherErreur(err);}catch(_){}
    }

    setTimeout(function(){
      try{delete t.row.dataset.cdqPdfOpenedV2275;}catch(_){}
    },800);
  },true);

  document.addEventListener('click',function(e){
    const row=e.target&&e.target.closest?e.target.closest('.file-row'):null;
    if(!row||row.dataset.cdqPdfOpenedV2275!=='1')return;
    e.preventDefault();
    e.stopImmediatePropagation();
    delete row.dataset.cdqPdfOpenedV2275;
  },true);
})();
